questions.questionText:
¿Qué muestra?
static bool T(string s) { Console.Write(s); return true; }
static void Run(int n)
{
    switch (n)
    {
        case int v when T("a") && v > 5: Console.Write("X"); break;
        case int v when T("b"): Console.Write("Y"); break;
        default: Console.Write("Z"); break;
    }
}
Run(3);

