Puerta p = Puerta.Cerrada;
int cambios = 0;
foreach (char ev in "bbdaa")
{
    Puerta antes = p;
    switch (p)
    {
        case Puerta.Cerrada:
            if (ev == 'a') p = Puerta.Abierta;
            else if (ev == 'b') p = Puerta.Bloqueada;
            break;
        case Puerta.Abierta:
            if (ev == 'c') p = Puerta.Cerrada;
            break;
        case Puerta.Bloqueada:
            if (ev == 'd') p = Puerta.Cerrada;
            break;
    }
    if (p != antes) cambios++;
}

